REASON = "Talab: komandirlar va kurs lavozimlaridagi kursantlar sutkalik naryadga qo‘yilmaydi (CLAUDE.md 10-bo‘lim, 56-band)."


def mark_exempt(apps, schema_editor):
    Cadet = apps.get_model("naryad", "Cadet")
    ChangeLog = apps.get_model("naryad", "ChangeLog")
    if not Cadet.objects.exists():
        return  # yangi baza — load_roster roster.json dagi belgini qo'yadi
    found, errors = [], []
    for group, last, first, patronymic, position in EXEMPT:
        matches = list(
            Cadet.objects.filter(group__code=group, last_name=last, first_name=first, patronymic=patronymic)
        )
        if len(matches) != 1:
            errors.append(f"{group} — {last} {first} {patronymic}: {len(matches)} ta mos keldi (1 ta bo‘lishi kerak)")
        else:
            found.append((matches[0], position))
    if errors:
        raise RuntimeError(
            "Naryaddan ozod kursantlarni aniq topib bo‘lmadi, migratsiya to‘xtatildi (taxmin qilinmaydi):\n  "
            + "\n  ".join(errors)
        )
    for cadet, position in found:
        if cadet.duty_exempt and cadet.duty_position == position:
            continue
        cadet.duty_exempt = True
        cadet.duty_position = position
        cadet.save(update_fields=["duty_exempt", "duty_position"])
        ChangeLog.objects.create(
            action="cadet_exempt", cadet=cadet, reason=REASON, details=f"Lavozimi: {position} (migratsiya 0010)"
        )


